    """
    This is a class for parsing command line arguments to a dictionary.
    """

    def __init__(self):
        """
        Initialize the fields.
        """
        self.arguments = {}
        self.required = set()
        self.types = {}

    def add_argument(self, arg, required=False, arg_type=str):
        """
        Adds an argument to self.types and self.required.
        """
        # Accept both type objects and string names for arg_type
        if isinstance(arg_type, str):
            # Map string to type
            type_map = {
                'int': int,
                'float': float,
                'str': str,
                'bool': bool
            }
            arg_type = type_map.get(arg_type, str)
        self.types[arg] = arg_type
        if required:
            self.required.add(arg)

    def _convert_type(self, arg, value):
        """
        Try to convert the type of input value by searching in self.types.
        """
        arg_type = self.types.get(arg, str)
        try:
            if arg_type == bool:
                # Accept several representations for booleans
                if isinstance(value, bool):
                    return value
                if isinstance(value, str):
                    if value.lower() in ('true', '1', 'yes', 'on'):
                        return True
                    elif value.lower() in ('false', '0', 'no', 'off'):
                        return False
                return bool(value)
            return arg_type(value)
        except Exception:
            return value

    def parse_arguments(self, command_string):
        """
        Parses the given command line argument string and stores the parsed result in arguments.
        Checks for missing required arguments.
        """
        import shlex
        tokens = shlex.split(command_string)
        # Skip the script name and possibly the interpreter
        # Find the first token starting with '-' or '--'
        i = 0
        while i < len(tokens) and not tokens[i].startswith('-'):
            i += 1
        args = tokens[i:]
        idx = 0
        while idx < len(args):
            token = args[idx]
            if token.startswith('--'):
                # Long option
                if '=' in token:
                    key, value = token[2:].split('=', 1)
                    self.arguments[key] = self._convert_type(key, value)
                else:
                    key = token[2:]
                    # Check if next token is a value or another option
                    if idx + 1 < len(args) and not args[idx + 1].startswith('-'):
                        value = args[idx + 1]
                        self.arguments[key] = self._convert_type(key, value)
                        idx += 1
                    else:
                        # Flag
                        self.arguments[key] = True
            elif token.startswith('-'):
                # Short option
                key = token[1:]
                if idx + 1 < len(args) and not args[idx + 1].startswith('-'):
                    value = args[idx + 1]
                    self.arguments[key] = self._convert_type(key, value)
                    idx += 1
                else:
                    self.arguments[key] = True
            idx += 1
        # Check for missing required arguments
        missing = self.required - self.arguments.keys()
        if missing:
            return (False, missing)
        return (True, None)

    def get_argument(self, key):
        """
        Retrieves the value of the specified argument from the arguments dictionary and returns it.
        """
        return self.arguments.get(key, None)

class AssessmentSystem:
    """
    This is a class as an student assessment system, which supports add student, add course score, calculate GPA, and other functions for students and courses.
    """

    def __init__(self):
        """
        Initialize the students dict in assessment system.
        """
        self.students = {}

    def add_student(self, name, grade, major):
        """
        Add a new student into self.students dict
        :param name: str, student name
        :param grade: int, student grade
        :param major: str, student major
        """
        self.students[name] = {
            'name': name,
            'grade': grade,
            'major': major,
            'courses': {}
        }

    def add_course_score(self, name, course, score):
        """
        Add score of specific course for student in self.students
        :param name: str, student name
        :param course: str, course name
        :param score: int, course score
        """
        if name in self.students:
            self.students[name]['courses'][course] = score

    def get_gpa(self, name):
        """
        Get average grade of one student.
        :param name: str, student name
        :return: if name is in students and this students have courses grade, return average grade(float)
                    or None otherwise
        """
        if name not in self.students:
            return None
        courses = self.students[name]['courses']
        if not courses:
            return None
        scores = list(courses.values())
        return sum(scores) / len(scores)

    def get_all_students_with_fail_course(self):
        """
        Get all students who have any score blow 60
        :return: list of str ,student name
        """
        result = []
        for name, info in self.students.items():
            if any(score < 60 for score in info['courses'].values()):
                result.append(name)
        return result

    def get_course_average(self, course):
        """
        Get the average score of a specific course.
        :param course: str, course name
        :return: float, average scores of this course if anyone have score of this course, or None if nobody have records.
        """
        scores = []
        for info in self.students.values():
            if course in info['courses']:
                scores.append(info['courses'][course])
        if not scores:
            return None
        return sum(scores) / len(scores)

    def get_top_student(self):
        """
        Calculate every student's gpa with get_gpa method, and find the student with highest gpa
        :return: str, name of student whose gpa is highest
        """
        top_name = None
        top_gpa = None
        for name in self.students:
            gpa = self.get_gpa(name)
            if gpa is not None:
                if (top_gpa is None) or (gpa > top_gpa):
                    top_gpa = gpa
                    top_name = name
        return top_name

