from typing import List

class CombinationCalculator:
    """
    This is a class that provides methods to calculate the number of combinations for a specific count, calculate all possible combinations, and generate combinations with a specified number of elements.
    """

    def __init__(self, datas: List[str]):
        """
        Initialize the calculator with a list of data.
        """
        self.datas = datas

    @staticmethod
    def count(n: int, m: int) -> int:
        """
        Calculate the number of combinations for a specific count.
        """
        if not (0 <= m <= n):
            return 0
        # Use math.comb if available (Python 3.8+), else fallback to factorial
        try:
            return math.comb(n, m)
        except AttributeError:
            # Implement comb manually
            return math.factorial(n) // (math.factorial(m) * math.factorial(n - m))

    @staticmethod
    def count_all(n: int) -> int:
        """
        Calculate the number of all possible combinations.
        """
        if n <= 0:
            return 0
        total = (1 << n) - 1  # 2^n - 1
        if total > 2**63 - 1:
            return float('inf')
        return total

    def select(self, m: int) -> List[List[str]]:
        """
        Generate combinations with a specified number of elements.
        """
        n = len(self.datas)
        if not (1 <= m <= n):
            return []
        result = []
        self._select(0, [None] * m, 0, result)
        return result

    def select_all(self) -> List[List[str]]:
        """
        Generate all possible combinations of selecting elements from the given data list.
        """
        n = len(self.datas)
        all_results = []
        for k in range(1, n + 1):
            all_results.extend(self.select(k))
        return all_results

    def _select(self, dataIndex: int, resultList: List[str], resultIndex: int, result: List[List[str]]):
        """
        Generate combinations with a specified number of elements by recursion.
        """
        n = len(self.datas)
        m = len(resultList)
        # If the combination is complete, add a copy to result
        if resultIndex == m:
            result.append(resultList.copy())
            return
        # If not enough elements left to fill the combination, return
        if dataIndex >= n:
            return
        for i in range(dataIndex, n):
            resultList[resultIndex] = self.datas[i]
            self._select(i + 1, resultList, resultIndex + 1, result)
